func AppendSearchMetadata(dst []byte, v *SearchMetadata) ([]byte, error) {
	return v.odjsonAppend(dst, odjsonrt.ModeHTML)
}

// odjsonSizeSearchMetadata sizes the buffer MarshalSearchMetadata allocates.
var odjsonSizeSearchMetadata odjsonrt.SizeHint

// MarshalSearchMetadata returns the JSON encoding of v.
func MarshalSearchMetadata(v *SearchMetadata) ([]byte, error) {
	buf, err := v.odjsonAppend(odjsonSizeSearchMetadata.New(), odjsonrt.ModeHTML)
	if err != nil {
		return nil, err
	}
	odjsonSizeSearchMetadata.Record(buf)
	return buf, nil
}

// UnmarshalSearchMetadata decodes the JSON document data into v.
func UnmarshalSearchMetadata(data []byte, v *SearchMetadata) error {
	p, err := v.odjsonParse(data, odjsonrt.SkipSpace(data, 0))
	if err != nil {
		return err
	}
	return odjsonrt.EndOfDocument(data, p)
}

// MarshalJSON implements encoding/json.Marshaler.
func (v SearchMetadata) MarshalJSON() ([]byte, error) {
	return MarshalSearchMetadata(&v)
}

